// Integration-ready editorial draft; publication and clinical approval are separate decisions.
// Procurement recommendations are original editorial synthesis, not clinical protocols.
// Source IDs resolve in editorial-sources.mjs; manufacturer examples are not endorsements.
const section = (title, text, sources = []) => ({ title, text, sources });
const equipment = (id, summary, sections, checklist, service, sources) => ({
  id, summary, sections, checklist, service, sources,
  kind: 'equipment', status: 'Integration-ready editorial draft', updated: '2026-10-16',
});

export const equipmentGuidance = [
  equipment('ultrasound',
    'Start with the examinations and the probes. The right ultrasound package is the one your team can use, clean, document and support in its own setting.', [
    section('Specify the examination before the machine', 'Ask the clinicians who will scan to define the examinations, patient groups and required imaging functions. Then build a probe list around that work. A small handheld unit may suit a mobile service, while a cart may better fit a busy room with multiple transducers and users. Neither format is automatically the better purchase. Have the team assess a demonstration against the same practical tasks, including handling the probe and saving a study.'),
    section('Make probe compatibility visible', 'Transducer compatibility is specific to the system and examination; the Sonosite reference illustrates why a probe family name alone is insufficient. Put the exact system, probe model, software options and included quantities in the quote. For an existing unit, request a documented inspection of the lens, cable and connector and an image-quality assessment by qualified personnel. Ask separately about probe repair or replacement coverage.', ['probes']),
    section('Plan the everyday workflow', 'Walk through charging, movement between rooms, image export and cleaning. If a tablet, account or subscription is involved, establish who owns it and what happens when a device or staff member changes. Have infection-prevention staff confirm the approved reprocessing workflow for each probe. Include covers, cleaning products, carts and replacement batteries in the ownership comparison; a machine that arrives without its usable probe package is an incomplete purchase.')
    ], ['Agreed examination list and required modes', 'System and transducer part numbers', 'Image export, account and license terms', 'Unit-specific probe and battery assessment'],
    'For support, identify the system and affected probe separately. Describe whether the issue occurs with one probe, one port or every examination, and provide the exact error text. Use approved, de-identified test images when requested; let the service team specify any diagnostic steps.', ['probes', 'reprocessing']),

  equipment('xray',
    'A detector, a mobile X-ray unit and a C-arm are different purchases. Compare each as a complete imaging workflow, including the room and the people who will keep it working.', [
    section('Separate radiography from procedural imaging', 'Define whether the project needs general radiography, bedside imaging or imaging during procedures. For a fixed or mobile X-ray system, ask the radiology team to specify examinations, positioning and detector requirements. For a C-arm, ask the procedural team to assess the usable imaging field and clearance around the intended table. Avoid comparing a detector retrofit with a complete generator, table and workstation package as though their prices describe the same scope.'),
    section('Commission the site plan early', 'Manufacturer site-planning services explicitly address installation, rigging, networking and room preparation. Obtain requirements for the actual offered system and have the facility and radiation-safety team approve them before committing to delivery. Assign responsibility for shielding design, electrical work, access routes and local acceptance. A general room drawing cannot establish that a particular building is ready.', ['imagingSite']),
    section('Protect the expensive components', 'Request the offered unit’s service history and documented image-quality checks. Identify detector, tube, battery, workstation and software coverage individually. Ask what happens if a detector is damaged and how images remain accessible if the workstation fails. Include image-storage connections, licenses, installation, training and engineer travel in the comparison. For a C-arm, include footswitches, displays and the configuration demonstrated to your team.')
    ], ['Clinical imaging and positioning requirements', 'Complete component and software list', 'Approved room and delivery plan', 'Detector and tube coverage stated separately'],
    'Record the exact model, detector identity, software version and error message. Explain whether the issue concerns exposure, detector communication, movement or image transfer. Arrange technical review through the facility’s normal process; this guidance does not provide exposure settings or repair instructions.', ['imagingSite']),

  equipment('ct-mri',
    'Treat a CT or MRI purchase as an installed service. The scanner price is only one part of a project that also depends on construction, commissioning, staffing and specialist support.', [
    section('Choose around an approved service plan', 'CT produces cross-sectional images using X-rays; MRI uses magnetic fields and radiofrequency energy. Their clinical roles and site requirements differ. Let the radiology team define the examinations, expected demand and required capabilities before comparing model names. Ask suppliers to demonstrate how the exact hardware and licensed software meet that specification; a headline slice count or field strength cannot answer every workflow question.', ['ctBasics', 'mriBasics']),
    section('Get an engineered installation scope', 'Request model-specific drawings and a site survey covering access, structural constraints, power, cooling and networking. For MRI, involve the facility’s MR safety specialists in access control and the magnet-specific installation requirements. Assign de-installation, transport, rigging and commissioning to named parties. The Siemens site-planning material is an example of the coordinated work involved, not a design specification for another manufacturer’s scanner.', ['imagingSite']),
    section('Price the support exposure', 'For CT, request tube history, the basis of any usage information and explicit tube coverage. For MRI, list the supplied coils, their condition and the applicable magnet service arrangements. In both cases, confirm software transfer rights, current serviceability and the local response plan in writing. Compare the same operating horizon, including planned maintenance, major-component exclusions, engineer travel and the consequences of a prolonged outage.')
    ], ['Approved examination and capacity specification', 'Exact hardware, coils and licensed options', 'Site survey and assigned installation scope', 'Major-component coverage and service plan'],
    'Give the specialist service provider the system identity, current configuration, service history and exact failure information. Keep acquisition, image-transfer and facility-utility issues distinct in the report. Site changes or magnet work require the responsible qualified specialists.', ['ctBasics', 'mriBasics', 'imagingSite']),

  equipment('anesthesia',
    'Evaluate the workstation as part of the operating room’s complete anesthesia setup. Gas delivery, ventilation, monitoring and the local support plan must fit together.', [
    section('Have the anesthesia team define the package', 'Specify the patient groups, clinical functions and room workflow with the anesthesia team. List the workstation, vaporizers, breathing-system components, gas monitoring and patient monitoring individually. A photographed monitor or vaporizer may be outside the base quote. The Dräger instructions illustrate the detailed operating, gas-supply and accessory requirements attached to one workstation; obtain the correct documentation for the actual model and software offered.', ['anesthesia']),
    section('Check the facility interfaces', 'Have a qualified technical team verify the proposed connections to medical gases, electrical supply and waste-anesthetic-gas disposal arrangements. Resolve connector standards, cylinder provisions and backup arrangements during planning. Confirm that the necessary breathing circuits, sensors, absorbent arrangements and approved accessories can be obtained locally or through a reliable supply route. Avoid assuming that a familiar brand uses the same components across generations.'),
    section('Define acceptance and maintenance', 'Request service history, the work completed on any used unit and the evidence supporting its condition description. Agree who will perform installation and the documented acceptance process before clinical use. Ask about preventive maintenance, replacement sensors and batteries, specialist parts and the scope of any warranty. Clinical staff need model-specific orientation even when the workstation resembles equipment they already know.')
    ], ['Patient groups and required workstation functions', 'Vaporizers, monitors and accessories itemized', 'Gas, power and scavenging interfaces reviewed', 'Installation, acceptance and maintenance ownership'],
    'Include the workstation model and serial number, software version, displayed fault and relevant service history. Identify which module is affected. Clinical teams should follow their established backup arrangements; technical troubleshooting and return-to-service checks belong to qualified personnel using the manufacturer’s instructions.', ['anesthesia']),

  equipment('surgical-tables',
    'A table and a lighting system must work with the procedure, the patient position and the room. Assess the whole arrangement before choosing either from a specification sheet.', [
    section('Compare usable positioning', 'Ask the surgical team to identify required positions, patient population and imaging access. Have the supplier document the permitted load and movement limits for the intended orientation and accessories. A single maximum-weight figure does not establish suitability in every configuration. The Baxter example shows how height, tilt, slide and modular components are separate attributes worth checking.', ['tables']),
    section('Include the accessories that make it usable', 'Itemize mattresses, armboards, leg supports, clamps, head sections, controls and battery or charging equipment. Ask the team to review transfer height, access for staff and clearance for a C-arm or microscope in a representative setup. For lights, evaluate positioning, field coverage, controls and any required sterile handles. Ceiling-mounted equipment needs a confirmed structural and installation plan; a light head alone does not describe that project.'),
    section('Inspect movement and maintainability', 'For an existing table, request a qualified assessment of locks, brakes, movement, upholstery and controls, with service history. For lights, establish the condition of the suspension and availability of replacement components. Include installation, commissioning and staff orientation in the quote. Ask whether service requires removing the table or lighting assembly and what downtime that would create for the room.')
    ], ['Procedure and positioning requirements', 'Configuration-specific load limits', 'Complete accessory and control package', 'Room clearance and mounting plan'],
    'Describe the affected movement, control, brake or light component and record its model and serial number. Report unusual movement or drift through the facility’s equipment-safety process. Do not improvise repairs to load-bearing or suspended assemblies.', ['tables']),

  equipment('endoscopy',
    'Buy an endoscopy service around compatible scopes and a workable reprocessing pathway. The tower is only one part of the system.', [
    section('Specify the complete imaging chain', 'Have the clinical team identify the procedures and scope types. List every scope, processor, light source, display and required accessory, then obtain written compatibility for the offered combination. Confirm which image functions and documentation options are included. If components come from different generations, ask for a demonstration of that exact configuration instead of relying on the appearance of connectors.'),
    section('Resolve reprocessing before purchase', 'Reusable devices require their validated cleaning and disinfection or sterilization process. FDA guidance also emphasizes compatibility between an endoscope and an automated endoscope reprocessor. Have infection-prevention and reprocessing staff confirm the scope-specific workflow, compatible chemicals, adapters, drying and storage arrangements. Buying a reprocessor does not remove the need to follow the scope’s instructions.', ['reprocessing', 'aer']),
    section('Make scope condition part of the decision', 'Request unit-specific scope inspection and service records, including the basis for any refurbishment description. Ask qualified personnel to assess the relevant mechanical, optical and integrity checks. Discuss repair turnaround, loan equipment if offered, transport protection and exclusions for fluid or accidental damage. Budget for the accessories and reprocessing supplies consumed by the service, not only the processor and display.')
    ], ['Procedures and scope models', 'Written compatibility across the imaging chain', 'Approved scope-specific reprocessing workflow', 'Scope condition and repair arrangements'],
    'Identify the scope and tower components separately. Report whether the issue concerns image, illumination, articulation, leakage or an error code, without attempting unsupervised diagnosis. Follow facility handling and decontamination requirements before a service return.', ['reprocessing', 'aer']),

  equipment('electrosurgery',
    'Select the generator, instruments and recurring supplies as a compatible system. Output wattage alone is a poor purchasing specification.', [
    section('Define the required functions', 'Ask the surgical team to state which procedures and energy functions are required. Monopolar, bipolar and vessel-sealing capabilities must be confirmed for the exact generator and instruments. Medtronic’s FT10 documentation demonstrates that generator variants and functions need careful identification; a product-family label should not be treated as proof that every function is included.', ['energy']),
    section('Itemize the working system', 'List handpieces, approved instruments, cables, footswitches and any required return-electrode accessories. Confirm which items are reusable and which are single use, and obtain their part numbers and reorder route. Have the operating-room team assess storage, placement and the associated smoke-management arrangements under facility policy. A demonstration should use the configuration being quoted, with its actual controls and accessories.'),
    section('Compare ongoing supply and service', 'Estimate recurring supply needs using the facility’s own procedure volumes. Ask about instrument availability, minimum orders, shelf life and replacement cables. For a used generator, request the service record and documented performance assessment by qualified personnel. Establish software status, current technical support and how faults will be handled locally. Avoid assuming that an inexpensive generator makes a proprietary instrument-dependent service inexpensive to run.')
    ], ['Required energy functions and procedures', 'Exact generator variant and instrument compatibility', 'Cables, footswitches and consumables itemized', 'Documented condition and support route'],
    'Record the generator identity, connected instrument or accessory part number and exact fault message. Ask the technical team to determine the appropriate checks. This is procurement guidance, not advice on energy settings, use near implants or clinical technique.', ['energy']),

  equipment('surgical-microscopes',
    'A useful microscope fits the specialty, the operator and the room. Evaluate the optics together with the stand, viewing accessories and service support.', [
    section('Start with the working position', 'Identify the specialty and the procedures, then ask users to assess the required working distance, magnification, illumination and viewing angle. The ZEISS example shows that objective, eyepieces, suspension and documentation options are distinct choices. Its dental configuration should not be assumed suitable for another specialty. A demonstration with the intended seating or table setup is more informative than a magnification claim alone.', ['microscopeExample']),
    section('Price every viewing and mounting component', 'List the stand or mounting assembly, binocular tube, eyepieces, objective, assistant viewer and any camera or recording equipment. Confirm compatibility and the included adapters. Assess movement around the room, storage footprint and access to controls. If mounting to a wall or ceiling, obtain the structural and installation requirements for the actual assembly before arranging delivery.'),
    section('Assess optics and service together', 'For an existing unit, request a qualified assessment of optical condition, illumination, balancing, brakes and mechanical movement. Identify missing accessories and the cost of replacing them before deciding that the package is complete. Ask who can service the optical and mechanical assemblies and whether parts remain available. Budget for protective covers or drapes as applicable, approved cleaning supplies and staff orientation on the model.')
    ], ['Specialty and required working distance', 'Complete optics and viewing package', 'Mounting, clearance and installation requirements', 'Optical condition and specialist service access'],
    'Describe whether the problem affects focus, image clarity, illumination, balance or movement. Identify any recently added accessory. Have qualified service personnel assess internal optics, electrical work and balancing; these are not buyer adjustment instructions.', ['microscopeExample']),

  equipment('airway',
    'Airway visualization depends on the compatible monitor, cable and blade or scope package. Plan for the full range of sizes and the supplies that keep it ready.', [
    section('Build the configuration around the clinical team', 'Ask the clinicians to define patient groups, required blade or scope formats and the intended location of use. A portable screen and a cart-based monitor may serve different workflows. Put the monitor, cable, blade and scope part numbers in the request. Verathon’s compatibility tables illustrate why products sharing a brand or looking physically similar cannot automatically be mixed.', ['airway']),
    section('Decide how supplies and reprocessing will work', 'Distinguish reusable components from single-use components on the packing list. For reusable equipment, have infection-prevention staff confirm the manufacturer-approved process and local access to the necessary supplies. For single-use items, establish sizes, storage, shelf life, reorder quantities and delivery lead times. Evaluate the ongoing supply plan before choosing a platform; the screen cannot provide a service without compatible patient-contact components.', ['airway']),
    section('Check readiness beyond the display', 'Ask about battery condition, charging, spare cables, transport protection and available service. In a used package, request a demonstration and documented condition assessment of the actual components. Include orientation for users and responsibility for routine readiness checks in the implementation plan. The clinical department should set its own backup-equipment requirements and training arrangements.')
    ], ['Patient groups and required blade or scope formats', 'Monitor, cable and component compatibility', 'Single-use supply or reusable processing plan', 'Battery, charging and spare-component arrangements'],
    'Identify the monitor and attached components, describe the image or power problem and give the exact error text. Follow the facility’s equipment-safety process and the manufacturer’s service instructions. Do not include patient video or identifying images in a routine service inquiry.', ['airway']),

  equipment('ventilators',
    'Choose a ventilator around the patient groups, clinical workflow and support capacity of the receiving facility. A long feature list does not establish that a unit is ready for that setting.', [
    section('Have the clinical team define the specification', 'Document the intended patient groups, ventilation functions, monitoring requirements and whether use includes transport. Confirm each capability on the exact software and hardware configuration offered. Some functions or patient categories may require specific options and accessories. Hamilton’s C1 material illustrates a turbine-based system and configuration choices; it is an example, not a capability statement for other ventilators.', ['ventilation']),
    section('Match gases, power and consumables', 'Have the technical team verify oxygen and air requirements, connector standards, power supply and battery arrangements against the model instructions. List breathing circuits, flow sensors, exhalation components, humidification equipment and other approved accessories. Confirm which parts are reusable and which need replacement. The purchasing decision should include a reliable source for those items and the approved cleaning or reprocessing workflow.'),
    section('Plan acceptance and continuity', 'Request service history and a documented condition assessment for an existing unit. Agree who will install, check and accept the equipment before use and who will orient staff. Ask about preventive maintenance, sensor and battery replacements, specialist test equipment and the local repair route. The clinical service should decide its backup capacity and how care will continue when a ventilator is unavailable; a quoted repair response time alone does not settle that plan.')
    ], ['Clinical specification and patient groups', 'Installed modes and options confirmed', 'Gas, power and complete accessory requirements', 'Acceptance, maintenance and backup responsibility'],
    'Provide the model, serial number, software version, alarm wording and relevant service history. Explain the operational impact without sharing patient identifiers. Trained teams should follow their clinical contingency procedures; troubleshooting must use the applicable manufacturer instructions.', ['ventilation']),

  equipment('ekg',
    'Patient monitoring, diagnostic ECG and defibrillation are separate functions. Start by naming the job each device must do, then compare the complete configuration.', [
    section('Keep the three equipment roles clear', 'For bedside monitoring, list the required parameters and patient groups. For a diagnostic ECG, define acquisition, reporting and record-transfer needs. For a defibrillator, have the clinical team specify the intended users and required functions. Do not assume that a monitoring screen replaces a diagnostic ECG system or that every defibrillator includes the same monitoring, pacing or advisory functions.'),
    section('Count the modules and accessories', 'Monitoring capability depends on the installed measurement hardware and accessories; Philips’ modular system is one example. Itemize compatible cuffs, leads, sensors, cables, modules and mounting equipment. For ECG, establish computer, software and connectivity requirements. For defibrillation equipment, confirm the approved pads or paddles, battery, charger and model-specific documentation. A feature visible on a brochure may require an option absent from the quoted unit.', ['monitoring', 'ecg', 'defibrillation']),
    section('Budget for readiness and replacement', 'Compare recurring sensors, electrodes and pads, battery replacements, software support and planned technical checks. Ask how central-station or record-system connections will be commissioned and who supports each interface. For used devices, obtain unit-specific service and condition records. Arrange staff orientation and a documented acceptance process; the clinical and technical teams should define readiness checks and alarm policies.')
    ], ['Separate monitoring, ECG and defibrillator requirements', 'Installed modules and compatible patient accessories', 'Software, network and record-system scope', 'Battery and expiring-supply replacement plan'],
    'Identify the device and the connected sensor, lead or module. Distinguish missing measurements from network or report-transfer faults and provide exact messages. Service reports should use test data or properly de-identified records, not patient records.', ['monitoring', 'ecg', 'defibrillation']),

  equipment('neonatal',
    'Maternal monitoring, neonatal thermal care and phototherapy require different equipment. Build the purchase around the service your team intends to provide and the accessories each system needs.', [
    section('Separate the clinical functions', 'Ask the maternal and neonatal teams to identify whether the requirement is fetal or maternal monitoring, an incubator, a radiant warmer, phototherapy or several of these. An incubator and a warmer provide different working environments; a combined model must be evaluated in its actual configuration. The GE incubator reference illustrates how temperature control, humidity and access features belong to a specific design.', ['neonatal']),
    section('Check the complete care station', 'Itemize required probes, mattresses, scales, monitors and other accessories, and confirm compatibility. Have users assess visibility, access for care, cleaning access and movement between locations. For phototherapy, request the manufacturer’s performance documentation and the prescribed method for checking light output. For maternal or fetal monitors, list the required transducers and recording supplies. Accessories from a general photograph should not become assumed inclusions.'),
    section('Make technical support part of readiness', 'Request service history, condition documentation and evidence that applicable manufacturer corrections have been addressed. Have qualified staff define acceptance checks for the offered equipment rather than relying on a power-on demonstration. Include replacement probes, batteries, consumables and planned maintenance in the budget. Establish how the facility will keep the service operating during repair and who owns the follow-up on safety notices.')
    ], ['Separate maternal, thermal-care and phototherapy needs', 'Compatible probes, mattresses and options', 'Documented condition and applicable correction status', 'Acceptance and ongoing service responsibility'],
    'Provide the device model, serial number and specific affected function. Record displayed errors and recent service changes. Temperature-control or monitoring concerns should follow the facility’s equipment-safety and clinical contingency procedures, with technical assessment by qualified personnel.', ['neonatal', 'recalls']),
];

equipmentGuidance.push(
  equipment('oxygen',
    'Plan the oxygen source and the delivery equipment together. Concentrator output and the total gas flow of a high-flow system describe different things.', [
    section('Specify the oxygen service', 'Have the clinical and technical teams define the required oxygen delivery, expected simultaneous use and backup arrangements. WHO’s concentrator guidance addresses selection, procurement and maintenance as connected decisions. Ask the supplier to document performance under the site’s environmental conditions and the relevant flow and pressure requirements. A concentrator’s nominal flow label does not establish compatibility with every connected device.', ['oxygen']),
    section('Distinguish high-flow equipment from the oxygen source', 'A heated high-flow system includes its own specified humidification, breathing circuit and patient interface, and may require an external oxygen supply. Fisher & Paykel’s Airvo material illustrates the distinction between the system’s total flow and adding oxygen. Have the technical team confirm the entire proposed arrangement; do not use a shared number in litres per minute as evidence that two devices can meet each other’s requirements.', ['highFlow']),
    section('Budget for continued operation', 'Include power reliability, replacement filters, approved circuits, interfaces, water requirements and the equipment used for planned performance checks. Establish who will maintain the source and the delivery devices and how replacement parts will reach the site. Review storage and placement with the facility’s responsible team. A complete proposal should show how the service will continue during power loss, maintenance or supply interruption, using the facility’s approved contingency plan.')
    ], ['Required oxygen service and simultaneous demand', 'Source output and device input compatibility', 'Circuits, interfaces and humidification supplies', 'Maintenance, power and backup arrangements'],
    'Identify whether the concern is the oxygen source, humidifier, flow device or interface. Provide model details and exact alarm text. Performance verification and repair require the appropriate trained personnel and test equipment; clinical settings must be determined by the treating team.', ['oxygen', 'highFlow']),

  equipment('infusion',
    'A pump purchase includes a continuing commitment to compatible administration sets or syringes, staff training and technical support. Compare that whole arrangement.', [
    section('Specify the delivery task', 'FDA describes infusion pumps as devices that deliver fluids in controlled amounts. Have clinical staff define the intended care areas, patient groups and required pump functions. Separate syringe-pump and volumetric-pump requirements. If drug libraries, docking systems or central software are needed, identify them explicitly and agree who will configure and maintain them.', ['infusion']),
    section('Confirm the recurring supply', 'Require the supplier to name the approved administration sets or syringe types for the exact model. Record part numbers, local availability, minimum orders, shelf life and normal delivery times. Ask procurement to estimate annual use from the facility’s workload. A low equipment price can become less attractive if the compatible supplies are difficult to obtain or if many different pump families must be stocked.'),
    section('Evaluate implementation and support', 'For an existing unit, request service records, software version, battery condition and documented performance checks. Have the clinical and technical teams agree the acceptance process, user orientation and any software implementation work. Compare replacement batteries, maintenance, set prices and service terms across the same period. Clarify whether the offered service includes accessories, docking components and software support as well as the pump itself.')
    ], ['Clinical functions and pump type', 'Approved set or syringe part numbers', 'Software and training responsibilities', 'Battery, performance records and service scope'],
    'Record the pump model, software, error message and the relevant administration-set or syringe identity. Preserve appropriate device information under facility policy without sending patient identifiers. Suspected delivery problems require the facility’s clinical and equipment-safety response, not informal adjustment guidance.', ['infusion']),

  equipment('suction',
    'Choose suction equipment for the application, operating pattern and collection system. Vacuum, flow and portability each answer a different purchasing question.', [
    section('Describe where and how it will be used', 'Have the clinical team specify the application, required performance and whether the unit must move with staff or patients. Distinguish a portable battery unit from a stationary unit or a facility vacuum-system component. Manufacturer specifications, such as the Drive example, report vacuum and free-flow performance separately. Ask your technical team to compare the relevant specification under the intended conditions rather than judging the unit by one maximum number.', ['suction']),
    section('Include the fluid collection pathway', 'Itemize canisters, lids, liners if used, filters, tubing, connectors and transport brackets. Identify which parts are disposable and which have a validated reusable process. Confirm that replacements can be ordered by part number and that the facility can manage collection and disposal through its established infection-prevention workflow. A working pump without the correct collection components is not a ready-to-use system.'),
    section('Check batteries and maintenance access', 'For portable use, ask about battery condition, charging time and documented runtime under the manufacturer’s stated test conditions. Confirm the permitted operating pattern and planned maintenance requirements. For used units, request a qualified performance and condition assessment. Compare replacement filters, containers, batteries and servicing costs, including the practical route for returning equipment that has been used in a clinical environment.')
    ], ['Application and required vacuum/flow specification', 'Approved collection and filter components', 'Operating pattern and battery requirements', 'Consumable supply and maintenance plan'],
    'Describe the observed loss of suction, power issue, unusual noise or alarm and identify the collection system in use. Follow facility decontamination procedures for service returns. Internal inspection and performance testing should be directed by qualified service personnel.', ['suction']),

  equipment('laboratory',
    'Purchase a laboratory workflow, from sample preparation to a reportable result. The analyzer is valuable only when reagents, quality systems and local support are ready with it.', [
    section('Choose around the test menu and workload', 'Ask the laboratory team to define the tests, sample types, daily volume, peak workload and reporting requirements. Separate chemistry, hematology, microscopy, centrifugation and histology needs; these instruments do different jobs. Compare practical throughput, staffing and sample handling against the service you intend to operate, including how urgent work will fit around routine batches.'),
    section('Price reagents and quality activities', 'WHO’s laboratory procurement guidance highlights intended users, setting, reagent stability and shelf life as purchasing concerns. Ask for a complete list of reagents, calibrators, controls, consumables and storage requirements. Calculate cost using reportable tests and your own expected workload, allowing for quality activities, repeat work and material that expires before use. Keep those assumptions visible rather than accepting an unexplained cost-per-test figure.', ['laboratory']),
    section('Map the room and technical support', 'Document power, water, temperature, ventilation, waste and bench requirements for the selected instruments. Confirm software and laboratory-information-system connections where needed. For used equipment, request service history and a clear installation and acceptance scope. Ask who will train staff, support quality procedures and service the instrument locally. If a reagent agreement is proposed, review its minimum volumes, delivery terms and responsibilities alongside the equipment price.')
    ], ['Approved test menu, specimens and workload', 'Full reagent, control and calibrator requirements', 'Site utilities and reporting connections', 'Acceptance, training and local service arrangements'],
    'Identify the instrument, software, affected test or workflow and relevant reagent or control lot information. Share equipment and quality information through the laboratory’s approved process. Do not include identifiable patient results in a general service request.', ['laboratory']),

  equipment('point-of-care',
    'Near-patient testing needs a managed testing service as well as a compact reader. Start with the tests, consumables and quality responsibilities.', [
    section('Name the tests and the intended users', 'Ask the clinical and laboratory teams to agree which tests are needed, who will perform them and how results will be recorded and reviewed. Confirm the approved sample type and intended setting for the exact test. A reader may accept several cartridge families without making all panels available on every software version or in every market. Abbott’s cartridge instructions demonstrate why the device and test documentation must be reviewed together.', ['pointOfCare']),
    section('Evaluate storage and replenishment', 'Obtain cartridge or test-strip storage conditions, shelf life, pack sizes and the local delivery route. Estimate use by test type, including controls and potential wastage. A small service may find that its practical cost depends more on unused stock and supply reliability than on the reader’s purchase price. Have the laboratory lead define the necessary quality checks and operator training under the applicable instructions and local requirements.', ['laboratory']),
    section('Connect the result to the service', 'Clarify patient identification, result transfer, printer or network needs and responsibilities when the system is offline. Ask about software support, operator management and any ongoing fees. For a used reader, confirm account or license transfer and current support before ordering. Include initial training, the first usable supply package and a documented acceptance process in the proposal so arrival of the reader does not become the start of another procurement round.')
    ], ['Exact tests, specimens and intended setting', 'Compatible cartridges and storage requirements', 'Quality and operator-training ownership', 'Reporting, software and recurring supply terms'],
    'Provide the analyzer identity, software, error wording and relevant consumable lot and expiry information through the approved support route. Distinguish a device fault from a quality-control or supply issue; the laboratory lead should determine whether testing may continue.', ['pointOfCare', 'laboratory']),

  equipment('ophthalmology',
    'Retinal imaging, slit-lamp examination and tonometry are distinct parts of eye care. Specify the service first, then build a compatible package around it.', [
    section('Choose the tool for the task', 'Ask the eye-care team to identify the examination or imaging work, patient groups and working environment. A retinal camera creates an image, a slit lamp supports examination and a tonometer measures eye pressure. For imaging, define the required capture and review workflow as well as portability. The Topcon reference is an example of a handheld imaging platform, not evidence that every camera offers the same functions.', ['retinal']),
    section('Plan accessories and recurring items', 'List tables, stands, chin rests, power supplies, cameras, software and any necessary computer. For a tonometer, confirm the correct probe or other patient-contact consumable; iCare’s TP01 reference shows that compatibility and single-use status are product-specific. Have infection-prevention staff review the required process for reusable contact components. Establish reorder access before buying a device that depends on proprietary supplies.', ['tonometry']),
    section('Assess the room and the offered unit', 'Have users evaluate positioning, access and image or optical quality in a representative setup. For used equipment, request service records and a qualified assessment of optics, mechanics and measurement performance as applicable. Confirm software transfer, record export and support for the intended computer. Budget for calibration or other specified checks, replacement illumination components where applicable and the availability of a qualified local service route.')
    ], ['Required examinations and imaging workflow', 'Complete mounting, computer and accessory package', 'Compatible contact consumables and reprocessing plan', 'Optical or measurement assessment and service support'],
    'Describe whether the issue concerns illumination, focus, image capture, movement or measurement. Identify software and attached accessories. Technical checks should follow the model instructions; a purchasing guide cannot establish whether an examination result is clinically reliable.', ['retinal', 'tonometry']),

  equipment('clinical-essentials',
    'Build a clinic around a dependable examination workflow. Small devices deserve the same attention to fit, supplies and support as larger systems.', [
    section('Write a room-by-room equipment list', 'Start with the services and patient groups the clinic will support. Identify examination furniture, lighting, weighing and measurement equipment, basic diagnostic instruments and any specialty testing needs. State quantities by room and the accessories needed by the actual users. This makes it easier to see where shared equipment is workable and where moving it would interrupt the clinic.'),
    section('Check the measurement and the intended use', 'Ask clinical staff to specify appropriate cuff and sensor sizes, measurement ranges and device functions. For pulse oximeters, review FDA information on intended medical use and limitations, including factors that can affect accuracy; a numerical display alone does not establish suitability. For spirometry or hearing-testing equipment, have the responsible service define calibration, environment and consumable requirements rather than adding a device to a list without its workflow.', ['oximetry']),
    section('Standardize the practical details', 'Where clinically appropriate, compare common battery types, charging arrangements, approved accessories and cleaning products across rooms. Label the responsible owner for checks and replenishment. For secondhand equipment, identify the specific condition assessment required instead of using one generic power-on check for every device. Include replacement cuffs, probes, bulbs or light modules, printer supplies and other recurring items in the purchase plan.')
    ], ['Services, patient groups and room quantities', 'Correct sizes, ranges and intended-use documentation', 'Consumables, batteries and cleaning requirements', 'Named responsibility for checks and replenishment'],
    'Identify the exact device and accessory, explain what was observed and include the relevant checking or service history. Keep instrument problems distinct from clinical interpretation. The responsible clinician or technical team should determine the appropriate next step.', ['oximetry']),

  equipment('sterilization',
    'A sterilizer belongs within a complete instrument-processing workflow. Choose it around the loads your team must process and the utilities your site can provide.', [
    section('Define the loads before the chamber', 'Have the reprocessing team list the instruments, packaging and expected daily demand. Obtain the applicable instructions for those instruments and confirm that the proposed sterilizer has suitable validated cycles. Chamber volume by itself does not tell you whether the required trays or loads can be processed. The Midmark example shows how chamber dimensions, loading and cycle information are model-specific.', ['sterilizer']),
    section('Plan the surrounding work', 'Map the route from receiving used instruments through cleaning, preparation, packaging, processing and storage. Have infection-prevention and facilities staff review workspace, utilities, water requirements and waste arrangements. FDA’s reprocessing guidance makes clear that cleaning and subsequent disinfection or sterilization form a multistep process. Purchasing the final machine does not provide the earlier steps or establish a validated local workflow.', ['reprocessing']),
    section('Include monitoring and maintenance', 'Ask the responsible team to specify process monitoring, record keeping and the supplies needed under applicable instructions and policy. Request installation and acceptance responsibilities in writing. For an existing sterilizer, obtain service records and a qualified condition assessment. Compare seals, filters, trays, water treatment where needed, planned service and downtime arrangements. The final equipment choice should be supported by the people who will load, monitor and maintain it.')
    ], ['Instrument and packaging compatibility', 'Required usable load capacity and cycles', 'Approved workflow and site utilities', 'Monitoring, records and maintenance responsibilities'],
    'Provide the sterilizer model, cycle or error information, load context and recent service history. Have the responsible reprocessing and technical teams manage any failed process or equipment concern. This guide does not prescribe cycle parameters or authorize release of a load.', ['sterilizer', 'reprocessing']),

  equipment('beds',
    'Evaluate the bed, mattress, rails and accessories as a system. Patient handling and day-to-day maintenance matter as much as powered features.', [
    section('Match the care setting', 'Ask nursing and patient-handling staff to define the patient population, required positions, transfer needs and room layout. Compare low and working heights, access for care, transport routes and the controls users will need. For stretchers and transport furniture, assess movement and braking in the intended environment. Do not assume one ward’s bed specification suits every department.'),
    section('Keep the components compatible', 'FDA describes bed systems as the frame, mattress, rails and compatible accessories and highlights entrapment concerns. Require the supplier to identify the mattress and rail configuration and have the facility assess it for the intended use. Replacement mattresses or added accessories need compatibility review; choosing a mattress only by its outer dimensions is not an adequate purchasing process.', ['beds']),
    section('Inspect the parts that work every day', 'For used equipment, request condition records for the frame, mattress cover, rails, brakes, controls, actuators and batteries where fitted. Ask users to assess handling and cleaning access. Include delivery to the final room, assembly, inspection and staff orientation. Compare replacement mattresses, casters, control handsets and service access across the expected fleet, and identify who will respond when a bed becomes unavailable.')
    ], ['Care-setting and transfer requirements', 'Documented bed, mattress and rail compatibility', 'Condition of brakes, controls and patient surfaces', 'Delivery, assembly and replacement-parts scope'],
    'Report the specific movement, brake, rail, mattress or control concern and identify the bed system components. Follow the facility’s process for taking unsafe equipment out of use and obtaining technical review; do not modify rails or load-bearing parts informally.', ['beds']),

  equipment('refrigeration',
    'Choose refrigeration around the material being stored and the response plan when temperature leaves its permitted range. A cold cabinet alone is not a complete cold-chain service.', [
    section('Specify the storage purpose', 'Separate vaccine, medicine, reagent, specimen and blood-storage requirements. Ask the responsible clinical or laboratory service to define the applicable temperature range and equipment requirements for its products. Do not infer suitability from the word medical or assume vaccine guidance applies unchanged to blood or laboratory specimens. Compare usable capacity under the intended loading pattern, not only the cabinet’s advertised volume.'),
    section('Plan monitoring and response', 'For vaccines, CDC recommends purpose-built or pharmaceutical-grade units and appropriate continuous temperature monitoring. Its guidance provides a vaccine-specific starting point for equipment and handling decisions. Have the responsible service define alarms, data review, escalation, backup storage and transport arrangements. Confirm who receives an alarm outside working hours and what equipment and records are needed to act on it.', ['coldChain']),
    section('Check the room and ownership costs', 'Obtain installation clearances, ventilation, power and environmental requirements from the manufacturer. Review door access, shelving, security and alarm connections. For a used cabinet, request service history and evidence of temperature performance assessed under a suitable documented process. Include monitoring devices, calibration arrangements, backup power where required, maintenance and a plan for contents during repair. Set acceptance requirements before stock is moved into the unit.')
    ], ['Defined contents and product-specific storage requirements', 'Usable capacity and installation conditions', 'Monitoring, alarms and named response owner', 'Acceptance and emergency storage arrangements'],
    'Provide the refrigerator identity, relevant temperature records, alarm details and service history through the appropriate facility process. The responsible service must decide how affected stock is managed using product guidance; a repair conversation cannot establish whether it remains usable.', ['coldChain']),

  equipment('dialysis',
    'A dialysis machine must be assessed within the whole dialysis service. For hemodialysis, water quality, treatment and distribution are central parts of the project.', [
    section('Define the service with its clinical and technical leads', 'State the treatment service, intended equipment functions, workload and site requirements with the nephrology team. Separate the machine from the supporting water, consumable, monitoring and maintenance systems. CDC describes water treatment, storage, distribution and quality monitoring as essential considerations in hemodialysis. A machine-only quote cannot establish that a facility is ready to operate the service.', ['dialysis']),
    section('Commission the infrastructure plan', 'Have qualified specialists assess the incoming water and design the required treatment and distribution arrangements for the specific service and applicable standards. Assign responsibility for commissioning, sampling, disinfection procedures, routine checks and corrective action. Confirm power, drainage, space and consumable storage. Do not infer dialysis suitability from drinking-water quality or from the presence of a reverse-osmosis unit alone.', ['dialysis']),
    section('Compare the continuing commitment', 'Itemize compatible bloodlines, dialyzers, concentrates, filters, cleaning materials and other specified supplies. Request service history and documented condition for an existing machine, including applicable software and manufacturer updates. Agree installation, acceptance, staff training and local technical support. Build the budget around the planned service volume and include water-system maintenance, testing, spare parts and the consequences of an equipment or supply interruption.')
    ], ['Approved dialysis-service specification', 'Engineered water and site infrastructure plan', 'Compatible consumables and replenishment route', 'Commissioning, quality and maintenance responsibilities'],
    'Identify whether the issue concerns the treatment machine, water system, consumables or facility utilities. Give the qualified service provider the model, exact fault and relevant technical records. Clinical operation and return to service require the responsible specialist teams and applicable instructions.', ['dialysis']),
);

const opinion = (id, title, summary, intro, sections, checklist, related, sources) => ({
  id, title, summary, intro, sections, checklist, related, sources,
  kind: 'opinion', category: 'Procurement & service', status: 'Integration-ready editorial draft',
  updated: '2026-10-16',
});

export const opinionArticles = [
  opinion('the-price-of-a-working-service', 'Before you choose the lowest equipment quote',
    'Compare what it takes to put the same service into operation, then choose the proposal that makes the strongest case.',
    'Two quotes can name the same machine and buy very different things. One may deliver a working package; the other may leave probes, installation or software for the next purchase order. Our editorial view is that price competition works best when the proposals cover the same required service. Start with that complete scope, then ask where a simpler or less expensive option can meet the need.', [
    section('Make the proposals describe the same thing', 'Suppose two suppliers offer an ultrasound system. One quote includes the required probes, a cart, the necessary software and delivery to the facility. The other lists a console with accessories to be confirmed. The lower figure may eventually remain lower, but the first comparison is incomplete. Ask both suppliers to quote against one written configuration and identify every exclusion. Keep unknown costs as unknowns until someone supplies a defensible estimate; entering zero makes uncertainty look like a saving.'),
    section('Put recurring commitments beside the purchase price', 'For a laboratory service, WHO identifies reagent stability, shelf life and the intended setting as procurement considerations. That is a useful factual reminder that an instrument and its supply chain belong in the same decision. The broader purchasing method is straightforward: list the initial package, recurring consumables, maintenance, licenses and likely replacement items over an agreed period. Use the facility’s own volumes and assumptions. Show low and high scenarios for uncertain items instead of presenting a precise total built from guesses.', ['laboratory']),
    section('Treat an outage as an operational question', 'Downtime is difficult to price honestly. It can mean using another room, sending samples elsewhere, transferring work or postponing a service. Procurement should ask the department what it would do, how long that alternative is workable and which costs can reasonably be estimated. A supplier’s promise to answer a call within a day is different from a commitment to restore the equipment. Clarify response, diagnosis, parts supply, attendance and repair separately. If a loan unit is offered, confirm its availability and terms rather than assuming it exists.'),
    section('Do not turn total cost into an excuse to overbuy', 'A larger package is not automatically better. Remove features that the clinical team does not need, compare simpler suitable options and question optimistic workload projections. A sophisticated system can carry costs that do not produce useful capacity in the receiving facility. The aim is a complete minimum specification with room for justified growth, not the most elaborate proposal. Record who approved each essential requirement so the comparison can survive changes in staff or supplier.'),
    section('Build a comparison that can change the decision', 'Use one sheet with a row for each required component, installation task, recurring cost and service commitment. For each supplier, mark included, priced separately or unresolved. Compare expected workload with a lower-use scenario; this exposes minimum orders and fees that look attractive only at optimistic volumes. If the preferred quote changes under plausible assumptions, resolve the deciding uncertainty before ordering. Finish with a short explanation of why the selected package meets the service need and which risks the facility is accepting.')
    ], ['Compare identical required configurations', 'Show exclusions and unknown costs openly', 'Estimate recurring costs using local workload', 'Distinguish response promises from restoration plans'], ['ultrasound', 'laboratory', 'infusion'], ['laboratory']),

  opinion('refurbished-is-a-question-not-a-verdict', 'Refurbished equipment: buy the evidence',
    'Decide when a refurbished unit makes sense by checking its condition, complete configuration, acceptance terms and local support.',
    'A refurbishment label tells you what to ask next; it does not answer the questions. What work was done on this unit? Which parts and software are included? Who can repair it where it will be used? Our editorial position is that a documented, supportable refurbished package deserves a fair comparison with new equipment. The strength of the evidence should decide how far that comparison goes.', [
    section('Ask what happened to this unit', 'Request a description of the work completed, by whom, when and against what procedure. Ask for unit-specific photographs and available service records. A cleaned enclosure, a successful power-on and a replaced battery describe different levels of work. The supplier should explain its terminology instead of expecting the buyer to infer a uniform meaning from used, inspected or refurbished. If records are incomplete, document the uncertainty and decide what independent assessment is needed.'),
    section('Look for a coherent configuration', 'An older unit may have accumulated replacement components or software changes. List the current hardware, accessories and licensed functions and ask qualified reviewers to confirm that they form a supported configuration. For a monitor, this means the measurement modules and sensors, not only the display. Philips’ modular monitoring documentation provides a concrete example of how measurement capability sits in components that must be identified. A model name is too broad a description for the purchase order.', ['monitoring']),
    section('Check support in the place it will be used', 'A device that is serviceable in one country may be difficult to support in another. Ask who will provide local technical work, where parts come from and which software or documentation the service provider can legitimately access. Find out whether the manufacturer supports that generation and obtain the applicable instructions. Review relevant manufacturer notices and regulator recall information for the model and affected serial range. A database search is a useful input, not a certificate that an individual unit has no unresolved issue.', ['recalls']),
    section('Agree how condition will be accepted', 'Before payment and shipment, define the evidence that will support acceptance, the qualified party performing the checks and what happens if the equipment differs from the agreed package. Include freight damage and missing accessories in that discussion. Acceptance at dispatch and acceptance after transport serve different purposes. For equipment that requires installation, identify which checks depend on the final site and when the service or warranty period begins.'),
    section('Proceed, investigate or pause', 'Proceed with a refurbished candidate when it meets the clinical specification, its condition is documented, support is workable and the complete cost compares well. Investigate further when records are incomplete but a qualified independent assessment can answer the missing questions; price that assessment before deciding. Pause when essential compatibility, software transfer, parts access or acceptance rights remain unresolved. A new unit may earn its higher purchase price through a clearer support pathway, but verify its actual terms with the same care. Neither condition label replaces the evidence.')
    ], ['Ask for unit-specific condition and work records', 'Identify the complete supported configuration', 'Confirm local parts and service access', 'Agree acceptance criteria before shipment'], ['ekg', 'xray', 'endoscopy'], ['monitoring', 'recalls']),

  opinion('a-donation-should-start-with-the-recipient', 'A useful donation starts with the receiving team',
    'Make the recipient’s service plan, acceptance conditions and continuing costs the foundation of an equipment donation.',
    'A free machine can still create an unaffordable project. Freight, installation, compatible supplies and repairs belong to someone after the donation ceremony ends. Our editorial view is that the receiving facility should lead the specification and have a real opportunity to decline an unsuitable offer. The useful question is what service the donation will help that team sustain.', [
    section('Begin with a request that the facility owns', 'Ask the receiving clinical and technical teams to describe the service, the equipment gap and the essential requirements. Their priorities may differ from the donor’s available inventory. A facility may need several dependable examination devices before it needs a complex imaging system. Make those preferences visible early. The recipient should identify who can approve the clinical fit and who can approve the technical and operational arrangements.'),
    section('Treat acceptance as a joint decision', 'WHO’s 2024 donation guidance addresses inappropriate donations, responsibilities of donors and recipients, and the steps before, during and after a donation. That framework supports a simple editorial principle: do the difficult compatibility and responsibility discussions while the equipment can still stay where it is. Send accurate identification, condition records, configuration and photographs. Do not ask a recipient to accept equipment based only on a generous valuation or a short deadline.', ['donations']),
    section('Fund the parts of the project that are easy to overlook', 'Even when the equipment price is zero, packing, freight, local transport, site preparation, installation and staff orientation still need owners. Ongoing supplies, maintenance and eventual retirement also need a realistic plan. Build one shared budget and distinguish funded items from hoped-for contributions. If a donor can support only the machine, say so early so the recipient can determine whether the remaining commitment is manageable.'),
    section('Make the handover useful after the visitors leave', 'A good handover includes an equipment and accessory list, applicable instructions, the agreed acceptance record and a named support route. Training should reach the people who will use and maintain the equipment, with a plan for staff changes. Decide how the receiving team will report an issue and who is responsible for following it through. Avoid promises of continuing support that no organization has committed to provide.'),
    section('Make the shipment decision explicit', 'Approve shipment when the recipient has accepted the exact equipment, the site is ready and the essential costs and responsibilities have owners. Delay it when an unresolved dependency would prevent useful operation. If the offered machine does not fit, ask whether funding an identified repair, supplies or training would better serve the recipient’s priorities. Agree a proportionate follow-up covering installation, acceptance, intended use and support. These measures show what the donation accomplished after delivery and make a responsible delay easier to explain.')
    ], ['Recipient defines and approves the need', 'Condition and compatibility assessed before shipment', 'All costs and responsibilities assigned', 'Follow-up measures agreed with the receiving team'], ['clinical-essentials', 'oxygen', 'sterilization'], ['donations']),

  opinion('standardize-with-an-exit-plan', 'Standardize your fleet with a way to change course',
    'Capture the practical benefits of common equipment while keeping supply dependence, exceptions and future transition costs visible.',
    'A common fleet can make training, accessories and spare parts easier to organize. It can also make one supply interruption affect a much larger service. Our editorial view is to standardize where the practical benefits are clear, document the exceptions and preserve a workable route to change platforms. The next purchase should follow today’s evidence about the service, rather than the habit of repeating the last order.', [
    section('Count the practical gains before assuming them', 'Map the current fleet and ask staff where variation actually creates work. Separate issues such as different charging systems, multiple consumable stock lines, unfamiliar controls and fragmented service arrangements. Then identify which could be reduced by a common platform. Avoid claiming savings from a brand name alone. Two generations from the same manufacturer may still use different accessories, software or service procedures.'),
    section('Keep compatibility at the component level', 'Verathon’s airway documentation lists combinations of monitors, cables and scopes rather than treating compatibility as a general brand attribute. That is a useful example of the detail a fleet plan needs. Maintain an approved component list with exact part numbers and identify the combinations the facility has reviewed. When an item is replaced, check the list and documentation again instead of assuming that a newer part is a drop-in replacement.', ['airway']),
    section('Examine the supply commitment', 'Standardizing a pump or testing platform can concentrate demand on a small number of recurring supplies. Ask about supplier capacity, delivery history available for review, minimum orders, shelf life and the availability of approved alternatives. The important question is not whether dependence exists—many medical devices require specific supplies—but whether the facility understands and can manage it. Carrying a sensible buffer may be part of the answer, provided storage conditions and expiry make it practical.'),
    section('Allow clinically justified exceptions', 'A transport team, neonatal service and general ward may need different equipment. Let the clinical specification determine when an exception is warranted. Document the extra training, stock and support the exception will require, so it remains a conscious decision. A standard that forces a poor fit is not simplification; it moves complexity into daily work. Review the fleet plan as services change rather than treating it as permanent.'),
    section('Put an exit plan beside the fleet plan', 'Before a large commitment, establish how records can be exported, what software access survives the agreement and who controls configuration and training records. At renewal, compare continuing the platform with replacing one defined part of the fleet. Include retraining, remaining consumables, overlapping stock and integration work in the transition cost. Set a review trigger such as loss of parts support or an unmet clinical requirement. This makes staying a reasoned choice and changing a manageable project rather than an emergency response to a failed supply arrangement.')
    ], ['Identify actual sources of fleet complexity', 'Maintain component-level compatibility records', 'Review supply dependence and stock assumptions', 'Document exceptions and future transition needs'], ['airway', 'infusion', 'point-of-care'], ['airway']),

  opinion('service-starts-before-delivery', 'Negotiate equipment service before the first breakdown',
    'Turn “support included” into clear responsibilities for maintenance, parts, repair milestones and return to service.',
    '“We will respond tomorrow” does not tell a hospital when its equipment will work again. Our editorial view is to settle the important service questions while the purchase is still negotiable: who diagnoses the fault, who brings the parts, who pays for travel and what the department does in the meantime. A warranty is one part of that agreement. It needs a practical handover and a usable support route.', [
    section('Distinguish the kinds of support', 'A proposal may mention technical support, preventive maintenance, repair, parts coverage or training. These are different services. Ask who performs each, where it happens and what is excluded. Confirm whether engineer travel, freight, batteries, probes and other major accessories are covered. Do not turn a friendly assurance that help is available into an assumed service commitment; request a written scope that both parties can refer to.'),
    section('Define what the clock measures', 'A response commitment describes when someone will acknowledge or begin handling an issue. Attendance, diagnosis, parts delivery and restoration are separate milestones. Ask what information is needed to start the process and which hours and locations the arrangement covers. If the facility depends on a loan unit or backup machine, confirm the practical details in advance. Clinical departments should decide what disruption they can tolerate and what contingency service they need.'),
    section('Give the equipment a useful record', 'At handover, collect the serial number, configuration, instructions, acceptance documentation, maintenance requirements and support contacts in the facility’s asset record. Keep accessory identities where they affect compatibility. Record service events so a future technician can understand what changed. The first fault report should not require reconstructing the purchase from scattered emails and photographs.'),
    section('Plan for safety notices and changes', 'Manufacturers and regulators publish corrections and recalls that may affect particular models or serial ranges. FDA’s recall database is one public reference for U.S. information. Assign someone to receive applicable manufacturer notices and route them to the clinical and technical owners. A device being absent from one search does not establish that every update is complete. Preserve the evidence of any required corrective work with the unit’s records.', ['recalls']),
    section('Choose coverage against the disruption you can manage', 'Compare a broader service agreement with planned maintenance plus separately billed repairs using the same parts, labor, travel and freight assumptions. Separate billing may be workable where qualified local support and contingency capacity exist; broader coverage deserves consideration when a major repair bill or prolonged outage would be difficult to absorb. Confirm the exclusions in either case. Agree who performs the required checks and authorizes return to service under local procedures after repair. Put that final step in the written scope alongside response, attendance and parts-delivery responsibilities.')
    ], ['Separate maintenance, repair, parts and training scope', 'Define response, attendance and restoration terms', 'Create the asset record during handover', 'Assign notice tracking and return-to-service responsibility'], ['anesthesia', 'ventilators', 'ct-mri'], ['recalls']),
];

// Each guide has a distinct purchasing decision and a short, shareable reading entry point.
// These comparisons are editorial procurement judgments; the receiving team approves suitability.
const decision = (title, socialDescription, takeaways, choiceTitle, choiceText, sources = []) => ({
  title, socialTitle: title, socialDescription, takeaways,
  choice: section(choiceTitle, choiceText, sources),
});

const equipmentDecisions = {
  ultrasound: decision('Ultrasound: choose the probes before the platform',
    'Handheld or cart? Compare the examinations, probes, software and daily workflow before deciding which ultrasound package earns its place.', [
      'Shortlist systems against named examinations and exact probe models.',
      'Demonstrate image capture, cleaning and export with the quoted package.',
      'Price probe replacement, software access and batteries separately.',
    ], 'Handheld or cart: make the workload decide',
    'Consider a handheld package when movement between locations is central and the clinical team confirms it covers the required examinations. A cart deserves consideration when multiple probes, shared controls and a dedicated scanning workspace matter more than carrying weight. Test both against the same exam list and record-export task. Ask, “Which step of our daily work would this package make harder?” Include the tablet, cart, subscriptions and probes before comparing totals. A portable console with missing capabilities is not a saving.'),

  xray: decision('X-ray: retrofit, mobile unit or complete room?',
    'A detector upgrade and a complete X-ray room solve different problems. See which scope fits your project and what each quote must include.', [
      'Separate detector upgrades, mobile radiography and procedural imaging.',
      'Have a qualified team assess the existing room before choosing a retrofit.',
      'Get detector, tube, installation and image-transfer coverage in writing.',
    ], 'Upgrade a sound room or replace the whole system',
    'A detector retrofit is worth comparing when the existing generator, table and room remain suitable and supportable, with compatibility confirmed for the proposed upgrade. A complete replacement deserves consideration when those retained components also need work; price both paths through installation and acceptance. A mobile system fits a specified bedside workflow, while a C-arm belongs to a procedural-imaging specification. Ask the supplier to mark every retained, replaced and newly supplied component on one equipment list. That exposes an apparently cheap upgrade that leaves the expensive problem untouched.'),

  'ct-mri': decision('CT and MRI: what the scanner price leaves out',
    'Compare an installed imaging service: clinical capability, site work, licensed options, major-component cover and the plan for an outage.', [
      'Approve the examination plan before comparing scanner specifications.',
      'Compare delivered, installed and accepted scope on the same basis.',
      'Name the CT tube or MRI coils and magnet support in each proposal.',
    ], 'Decide what to retain and what to replace',
    'CT and MRI are not interchangeable bids; the radiology team first determines the service required. Within that service, compare a supported replacement configuration with any proposed upgrade to the existing system. Retaining equipment may reduce the project scope only if the remaining hardware, software and service arrangements still meet the plan. Ask for two complete scopes, including removal and site work, and identify who carries each unresolved cost. For a new service, confirm staffing and expected use before paying for capacity that the facility cannot yet operate.'),

  anesthesia: decision('Anesthesia workstations: buy the complete room package',
    'A workstation quote can omit the monitor, vaporizers or accessories you need. Compare the complete anesthesia setup and its support obligations.', [
      'List vaporizers, monitors, breathing components and options individually.',
      'Confirm gas, power and scavenging interfaces before shipment.',
      'Require model-specific acceptance, orientation and service scope.',
    ], 'A familiar fleet or a different platform',
    'Extending an existing workstation family can be attractive when staff familiarity, compatible accessories and local parts support are real advantages. A different platform may fit better when the current family cannot meet an approved clinical requirement or is becoming difficult to support. Compare the cost of retraining, accessory replacement and service tools alongside the machine. Ask the anesthesia team to identify which advanced options it will use and which are optional. Do not pay for a larger feature bundle while leaving an essential monitor or vaporizer outside the order.'),

  'surgical-tables': decision('Surgical tables and lights: prove the room fits',
    'Check positioning, imaging clearance, accessories and mounting before buying a surgical table or light from a headline specification.', [
      'Demonstrate the actual patient positions and imaging clearances.',
      'Verify permitted loads for each intended table configuration.',
      'Price accessories, mounting and installation as part of the package.',
    ], 'Versatility or a dedicated setup',
    'A general-purpose table with the right accessories merits consideration for a mixed procedure list. A more specialized configuration needs a clear requirement that the general setup cannot meet. Have staff demonstrate the intended positions with the quoted supports and imaging equipment; compare configuration-specific limits rather than the highest advertised load. For lighting, weigh a movable unit’s floor and storage needs against a ceiling installation’s structural work and fixed location. Ask for the room drawing and accessory list that explain how each proposed arrangement will work.', ['tables']),

  endoscopy: decision('Endoscopy: the tower is only part of the purchase',
    'Compare compatible scopes, reprocessing capacity and repair turnaround before committing to an endoscopy package.', [
      'Request a written scope-to-processor compatibility list.',
      'Size the scope inventory around reprocessing and repair interruptions.',
      'Approve the scope-specific cleaning, drying and storage pathway.',
    ], 'Spend on useful capacity before a newer tower',
    'Where the existing processor is supported and compatible with the required scopes, compare adding scope capacity with replacing the whole tower. A newer processor is worth considering when it provides a required capability or resolves a documented support problem. Ask the team to map a busy session: which scopes are in use, being reprocessed or unavailable for repair? That exercise may reveal that another compatible scope and sufficient processing capacity would help more than a display upgrade. Have reprocessing staff approve each proposed scope and reprocessor combination.', ['aer']),

  electrosurgery: decision('Electrosurgery: compare instruments as well as generators',
    'Generator price and wattage leave out much of the purchase. Match required functions to compatible instruments, supplies and support.', [
      'Confirm required functions on the exact generator variant.',
      'Get compatible instrument, cable and footswitch part numbers.',
      'Compare recurring instrument costs using your procedure mix.',
    ], 'Buy the functions your procedure list needs',
    'If the team requires conventional monopolar and bipolar functions, compare suitable packages against that specification. Consider a platform with additional sealing functions only when the surgeons identify a need and procurement can sustain its compatible instrument supply. Request separate prices for the base generator, enabled options and recurring instruments. Calculate a year of supplies from the expected procedure mix, including reusable-item processing where applicable. The useful comparison is the cost of the agreed work; a high-output specification or discounted generator cannot establish that value.', ['energy']),

  'surgical-microscopes': decision('Surgical microscopes: fit the operator, optics and room',
    'Magnification is only the start. Compare working distance, viewing position, mounting, documentation and the condition of the actual optics.', [
      'Have intended users demonstrate the required working position.',
      'Itemize every optical, viewing, mounting and camera component.',
      'Confirm specialist service and replacement parts for the offered unit.',
    ], 'Choose mounting and viewing options deliberately',
    'A floor stand is worth comparing when the microscope must move between rooms, provided doorways, storage and maneuvering space work. Wall or ceiling mounting may suit a dedicated room when the structural plan and working reach are established. Ask users whether an assistant viewer or recording system is essential; adding either later can require more than a camera purchase. For a used microscope, compare the price of replacing missing optics and adapters with a complete package. Inspecting the exact optical system matters more than the age of its enclosure.'),

  airway: decision('Airway visualization: choose a system you can keep ready',
    'Compare reusable and single-use components, sizes, batteries and reorder routes before choosing an airway visualization platform.', [
      'Match monitors, cables and blades or scopes by exact part number.',
      'Compare supply reliability with the work required for reprocessing.',
      'Include every required size, charging component and readiness owner.',
    ], 'Reusable or single use: compare the whole pathway',
    'Where both options meet the clinical specification, a reusable package deserves consideration when the facility can reliably provide the approved reprocessing and turnaround. A single-use component system deserves consideration when predictable replenishment and disposal can be supported; it still needs the rest of the platform kept ready. Compare a typical month’s usage, processing work, damaged-item replacement and stock that may expire. Ask what happens when one required size is unavailable. A monitor purchase should follow that supply decision, because the compatible blade or scope completes the working system.', ['airway']),

  ventilators: decision('Ventilators: match the unit to the service and site',
    'Compare patient groups, installed options, gas supply, batteries and consumables—not just a ventilator’s feature list.', [
      'Confirm patient groups and required functions on the offered configuration.',
      'Verify the gas source, power, battery and complete accessory package.',
      'Separate repair response promises from the clinical backup plan.',
    ], 'Evaluate portability without overlooking dependencies',
    'If transport is part of the service, require evidence that the exact ventilator and accessory configuration supports that use; a compact size alone does not establish it. Where compressed air is unavailable, a turbine-based option merits technical review, but oxygen, power and accessory requirements still need confirmation. The Hamilton example uses an integrated turbine and also identifies model-specific options. A stationary installation may prioritize the existing fleet and local support. Ask the team to compare both complete setups against the same clinical requirement, including the intended humidifier and mounting.', ['ventilation']),

  ekg: decision('Monitoring, ECG and defibrillation: specify each job',
    'Three different equipment roles, three different specifications. Compare modules, patient accessories, reporting and readiness costs.', [
      'Write separate requirements for monitoring, diagnostic ECG and defibrillation.',
      'Verify installed modules and compatible patient accessories.',
      'Budget for batteries, expiring supplies and connection setup.',
    ], 'Standalone equipment or a connected fleet',
    'A standalone device may fit when local display or reporting meets the department’s approved workflow. A connected monitoring or ECG package merits consideration when central observation or record transfer is required, with the network, software and receiving system included in the project. Ask for a demonstration that ends with the result visible in its intended destination. For defibrillation equipment, let the clinical lead specify users and required functions separately. Buying one device because it displays a familiar waveform can leave a different clinical job uncovered.'),

  neonatal: decision('Neonatal equipment: specify the whole care station',
    'Separate incubators, warmers, phototherapy and monitoring, then compare the accessories, access and support each care station needs.', [
      'Have the clinical team specify each maternal and neonatal function.',
      'List compatible probes, mattresses and required options in the quote.',
      'Check the exact unit’s condition, corrections and acceptance plan.',
    ], 'Separate devices or a combined platform',
    'Ask the neonatal team to define when it needs an incubator environment, warmer access and any other required functions before considering a combined platform. A combined unit deserves comparison if the team expects to use both configurations and can support the added equipment. Separate units may fit the planned workflow or service arrangements better. Compare available capacity when one unit is being cleaned or repaired, not only the number of functions in the brochure. Phototherapy and maternal monitoring remain separate specifications unless their exact equipment and accessories are included.'),

  oxygen: decision('Oxygen equipment: match the source to the demand',
    'Concentrator output and high-flow system flow are different specifications. Build a compatible oxygen service with a realistic backup plan.', [
      'Specify simultaneous demand and model-specific source requirements.',
      'Keep oxygen-source output distinct from total high-flow gas flow.',
      'Assign power, maintenance, consumable and backup responsibilities.',
    ], 'A source for one location or a wider service',
    'Compare a concentrator proposal with the facility’s existing cylinder or piped supply only after the technical team has specified demand, pressure and quality requirements. A concentrator introduces power and maintenance commitments; a cylinder proposal needs a workable replenishment and handling plan. A growing multi-location service needs a system design rather than an assumed multiplication of small-device ratings. Ask each supplier to show how the proposed source meets simultaneous demand and how the approved service continues during interruption. Keep the delivery equipment and its supplies in the same comparison.', ['oxygen']),

  infusion: decision('Infusion pumps: price the supplies before the fleet',
    'The pump price starts the comparison. Compatible sets, syringes, software ownership and training determine the continuing commitment.', [
      'Specify pump types and clinical functions before comparing models.',
      'Calculate compatible set or syringe use across the proposed fleet.',
      'Assign software, training, battery and service responsibilities.',
    ], 'A common platform or a specialist exception',
    'Extend a pump family when the clinical fit, supply availability and staff workflow support that choice. Compare a different platform when a required function is missing or the existing supply and service route is weak. Syringe and volumetric pumps still need separate clinical specifications. If a supplier proposes drug-library or fleet software, name the team that will maintain it and price implementation and recurring fees. Ask for pump-only and fully implemented totals. An inexpensive fleet can create a lasting cost if its approved sets are difficult to source.', ['infusion']),

  suction: decision('Suction equipment: compare the complete collection system',
    'Vacuum, flow, battery runtime and collection supplies each matter. Choose the package for the actual application and operating pattern.', [
      'Compare required vacuum, flow and permitted operating pattern.',
      'Itemize the canister, filter, tubing and disposable supply pathway.',
      'Check portable-unit battery evidence and charging arrangements.',
    ], 'Stationary or portable: test the operating pattern',
    'A portable unit deserves consideration when movement and operation away from mains power are required. For a fixed location with a suitable facility vacuum supply, compare the complete approved regulator and collection arrangement with a self-contained unit. Ask staff to describe the longest expected period of use and have the technical team match it to the offered equipment’s permitted operating pattern. For battery equipment, request runtime evidence under stated conditions. Portability is useful only if the unit, charger and collection components can support the planned work.'),

  laboratory: decision('Laboratory equipment: calculate cost per reportable result',
    'Compare the test menu, workload, reagent wastage and service terms. A low analyzer price can hide an expensive supply commitment.', [
      'Compare usable throughput against routine and urgent workload.',
      'Include controls, calibration, repeats and expiry in cost per result.',
      'Review minimum reagent purchases and exit terms beside the equipment price.',
    ], 'Buy the analyzer or commit to a reagent agreement',
    'An outright purchase deserves comparison when the facility can fund the instrument and its support. A reagent-linked placement or rental may fit when its minimum volume and supply terms match dependable demand. Compare both at expected and lower workload, including controls, calibration, wastage and maintenance. A larger analyzer earns consideration when it solves a documented capacity problem; unused throughput does not offset expired reagents. Ask what happens if testing volume falls, deliveries are late or the agreement ends. Those terms can matter more than the initial instrument charge.', ['laboratory']),

  'point-of-care': decision('Point-of-care testing: decide where the result is needed',
    'Near-patient testing needs cartridges, quality oversight and a reporting pathway. Compare its practical value with the existing laboratory route.', [
      'Identify which tests need a result near the patient and why.',
      'Estimate cartridge use and wastage by test type and pack size.',
      'Assign quality oversight, operator training and result transfer.',
    ], 'Near-patient testing or the existing laboratory route',
    'Ask the clinical team which decisions need a result sooner or in a location the existing laboratory pathway cannot adequately serve. Those requirements justify evaluating near-patient testing. Where the existing pathway meets the need, compare its cost and reliability before adding another testing platform. For a low-volume site, small pack sizes and manageable storage requirements may matter more than a broad test menu. Use expected demand for each cartridge, including quality activities and expired stock, to compare the actual cost of providing the required results.', ['laboratory', 'pointOfCare']),

  ophthalmology: decision('Eye-care equipment: build the examination pathway',
    'Retinal imaging, slit-lamp examination and tonometry serve different tasks. Compare positioning, supplies, record export and local service.', [
      'Specify imaging, examination and pressure-measurement needs separately.',
      'Demonstrate positioning and capture with the intended users.',
      'Confirm contact consumables, computer compatibility and export access.',
    ], 'Outreach portability or a dedicated examination room',
    'For outreach, compare the complete transport package: instrument, power, protective case, required computer and consumables. For a fixed service, ask users to assess positioning, furniture and repeated examinations in the intended room. A handheld imaging format may suit movement, but the eye-care team must confirm the required image quality and examination scope. Ask where images will be reviewed and how they leave the device. A camera purchase cannot substitute for an unmet slit-lamp or tonometry requirement simply because all three appear in an eye-care equipment list.'),

  'clinical-essentials': decision('Clinic equipment: make every examination room work',
    'Turn a clinic shopping list into a usable room plan, with the right sizes, shared equipment, replacement supplies and named responsibilities.', [
      'Allocate equipment by room, patient group and simultaneous demand.',
      'Check cuff, probe and sensor sizes for the people the clinic serves.',
      'Budget replacement supplies and assign replenishment ownership.',
    ], 'Dedicated room kits or a shared pool',
    'Equip each room with the essentials used in nearly every examination when moving them would delay the clinic. Consider sharing infrequently used specialty equipment when access, cleaning and accountability can be managed. Ask staff to walk through a busy session and identify where two rooms need the same item at once. Compare complete room kits rather than a box count: a blood-pressure device without the required cuff sizes leaves a gap. Standardize practical items such as chargers and replacement accessories only where the clinical specification permits.'),

  sterilization: decision('Sterilizers: compare usable loads and turnaround',
    'Chamber volume alone cannot choose a sterilizer. Compare actual trays, validated cycles, utilities, staffing and the plan for downtime.', [
      'Match instruments and packaging to suitable validated cycles.',
      'Compare usable trays per working day, including preparation and drying.',
      'Include monitoring supplies, utilities, maintenance and contingency capacity.',
    ], 'One larger chamber or capacity across smaller units',
    'Ask the reprocessing team to compare the actual trays and loads each suitable model can accept, with the full turnaround required by its instructions. A larger chamber may fit consolidated loads; smaller units may fit distributed demand or provide some continuity when one is unavailable. Neither is automatically the lower-cost choice. Include staffing, utilities, monitoring and the cost of the instrument inventory needed while a load is processing. Have the supplier demonstrate the proposed loading arrangement. Do not treat an empty chamber’s volume as a promise of daily usable capacity.'),

  beds: decision('Hospital beds: compare the whole patient-handling system',
    'Choose the frame, mattress, rails and accessories together, then compare everyday handling, cleaning and repair across the fleet.', [
      'Test transfer heights, controls and handling in the intended care setting.',
      'Confirm the exact frame, mattress and rail combination.',
      'Inspect brakes and surfaces and price fleet replacement parts.',
    ], 'Manual or powered features: justify the daily benefit',
    'Ask nursing and patient-handling staff which adjustments and patient controls the care setting requires. Compare suitable manual and powered configurations against that work rather than choosing by feature count. For powered beds, include batteries, handsets and actuators in the support discussion; for any bed, assess staff access and movement through the actual rooms. A common fleet can simplify parts stocking only when the generations and components are compatible. Avoid replacing a mattress purely on dimensions or price without reviewing its fit with the frame and rails.', ['beds']),

  refrigeration: decision('Medical refrigeration: buy a response plan with the cabinet',
    'Match the stored material, usable capacity, monitoring and backup arrangements before choosing medical refrigeration.', [
      'Specify product-specific storage requirements and peak inventory.',
      'Include temperature monitoring and a named after-hours responder.',
      'Agree acceptance and alternate storage before loading stock.',
    ], 'One large cabinet or separate storage capacity',
    'Compare capacity using the largest expected inventory with the required loading space, not the average stock level. One cabinet may simplify monitoring, while separate suitable units may help separate workflows and limit the stock affected by an individual failure. The latter still needs adequate power, monitoring and a transfer plan; two cabinets in the same power outage are not automatically a backup. For vaccines, CDC prefers purpose-built or pharmaceutical-grade units. Confirm that any proposed alternative meets the applicable storage requirements rather than relying on a “medical” label.', ['coldChain']),

  dialysis: decision('Dialysis: price the service beyond the machine',
    'Compare the treatment machine with water infrastructure, supplies, commissioning and maintenance as one dialysis-service project.', [
      'Approve the clinical service and water-infrastructure design together.',
      'Include commissioning, quality monitoring and recurring consumables.',
      'Compare the planned capacity with a realistic interruption scenario.',
    ], 'Expand an established service or build a new one',
    'An additional machine may be a sensible incremental purchase in an established service only after the qualified team confirms spare water-system, electrical, drainage, staffing and support capacity. A new unit or larger expansion needs an engineered service plan and its own infrastructure budget. Ask for separate machine, shared-infrastructure and recurring-cost totals so the next expansion is understandable. Model the proposed workload and what happens if a machine or shared system is unavailable. A low machine price does not establish that the extra treatment capacity can actually be delivered.'),
};

for (const guide of equipmentGuidance) {
  const { choice, ...presentation } = equipmentDecisions[guide.id];
  Object.assign(guide, presentation);
  guide.sections.splice(1, 0, choice);
}

